pub fn put_module(cwd: &Path, name: &str, program_cid: &str) -> String {
    let path = cwd.join(format!("{name}.module.json"));
    write_json(
        &path,
        &json!({
            "schema": "unicodex.program_module.v1",
            "kind": "program_module",
            "name": name,
            "entry": "main",
            "programs": {"main": program_cid},
            "metadata": {"fixture": "module-runtime"}
        }),
    );
    run_json(
        cwd,
        [
            OsStr::new("program"),
            OsStr::new("module"),
            OsStr::new("put"),
            path.as_os_str(),
            OsStr::new("--format"),
            OsStr::new("json"),
        ],
    )["cid"]
        .as_str()
        .unwrap()
        .to_owned()
}

